mapper.select:
SELECT id, user_id, device_name, device_type, serial_number, status FROM t_health_device  AND id = #{id}
 AND user_id = #{userId}
 AND device_name LIKE CONCAT('%', #{deviceName}, '%')
 AND device_type LIKE CONCAT('%', #{deviceType}, '%')
 AND serial_number LIKE CONCAT('%', #{serialNumber}, '%')
 AND status LIKE CONCAT('%', #{status}, '%') ORDER BY id DESC
